window.kbParts["paper-15a6fb5b9aaa5668"] = {"qs":{"江苏 2022 A类 申论#1":{"stem":"问题一\n\n内           “给定资料 1～3 中”列举了新时代出现的一些新职业，这些新职业对社会发展起到了\n        一定的积极作用，请用一段话对此进行概括。（20 分）\n\n                        料\n                   资       第 5 页 共 8 页\n\n                                        资\n                                部\n           要求：紧扣给定资料，准确全面，条理清晰，语言流畅。篇幅不超过 250 字。","options":[],"answer":"","analysis":"部\n                           内\n          新职业所引领的新业态是社会发展的新气象、新希望：1、快递人员用服务\n        回馈社会。不仅给客户送餐，还能在基础物资保障、城市发展、社会稳定方面发\n        挥重要作用；2、网络监督师帮助提高效率。帮助摆脱手机沉迷，找回时间，找\n                                                          料\n        回自律和信心；3、网上导购师促进理性消费。帮助客户以最合理的价格达成交\n        易，帮助客户合理购物；4、社群管理师促进规范管理。帮助企业维持群的活跃     部\n                料\n        度、增强用户粘性；5、制冰师促进冰雪运动发展。制作高质量冰面，助力冰雪\n        场地设施建设；6、助老员促进老有所养。提供助老服务，弘扬敬老美德，助力      资\n        部\n        中国梦实现。\n                                             内\n         资","figs":[],"state":"已标记","notes":[],"domains":["社会治理","经济"],"nature":"综合题","current":false,"links":[{"id":"k-23e7308f0d15a46c","label":"外卖配送对城市基本物资供应和运行的保障作用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"能在基础物资保障、城市发展，甚至社会稳定方面发挥重要作用。","why":"材料以疫情期间的配送服务说明骑手如何保障物资供应和城市运行。","origin":"逐题标记"},{"id":"k-8a09110ce76dd50c","label":"网络监督通过外部督促提高时间利用效率","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M2","quote":"体验了两周后，复习效率明显提高了。","why":"小叶的案例体现了外部督促对克服拖延、提高复习效率的作用。","origin":"逐题标记"},{"id":"k-02afaf07114ea3ce","label":"网上导购通过按需推荐和价格比较促进理性消费","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M2","quote":"还会根据客户的需求提出合理购物建议","why":"材料以按需建议和合理价格说明导购服务如何帮助消费者理性购物。","origin":"逐题标记"},{"id":"k-cd151706d0b1dd4e","label":"社群运营通过维护秩序和互动增强用户黏性","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M2","quote":"帮助企业维持群的活跃度、增强用户粘性。","why":"材料通过群规维护和及时回复说明社群管理师对企业线上社群的作用。","origin":"逐题标记"},{"id":"k-bb3deeff30e7c6f4","label":"专业制冰通过改善冰面质量支持冰雪场地供给","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M3","quote":"高质量的冰面赢得国内外选手一致点赞。","why":"专业制冰满足赛事用冰需求，为冰雪运动开展提供场地条件。","origin":"逐题标记"},{"id":"k-6bad75bb30c8e016","label":"社区助老服务通过生活照料和陪伴支持居家养老","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M3","quote":"黄女士时常会来陪她聊天，帮她整理房间。","why":"材料以陪伴、日常照料和就医协助说明助老员如何支持社区老人居家生活。","origin":"逐题标记"},{"id":"s-c898afc5816920c2","label":"从多则案例提炼各对象的作用并归并成段","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请用一段话对此进行概括。","why":"需要从多则职业案例中提炼各自的积极作用，并在字数限制内组织成一段。","origin":"逐题标记","originalId":"s-bcab6de661b7162f"}]},"江苏 2022 A类 申论#2":{"stem":"问题二\n\n                          内\n            “给定资料 4”中说“老一代有老一代的经验，新一代有新一代的兴趣，在鲜活的时\n        代画板上，社会成员间的互相理解与政府的适当引导往往是最好的调色剂。”请结合给定资\n        料 4、5，谈谈你的理解和认识。（20 分）\n           要求：观点正确，分析透彻，篇幅 250 字左右。                    料","options":[],"answer":"","analysis":"问题二（20 分）\n          这句话突显出两代人之间职业观存在冲突，这就需要社会成员间的相互理解和政府的适\n        当引导。\n\n    内     社会飞速发展，职业内涵不断延伸，但老一辈对新职业不了解，甚至存在误解。不管老\n        一辈理解与否，新行业的发展已成事实。《中华人民共和国职业分类大典》新收录的职业和\n\n\n                            资\n        工种，既反映就业方向的变化，也体现了政府服务与时俱进。人社部着力深化职称制度改革，\n        各地各部门针对不同群体量身定制评价标准，给新兴领域人才打开了职称大门，对于企业和\n\n\n                             料\n        行业来说，有利于吸引更多优秀人才，促进人才队伍建设，形成人才发展与产业发展相互促\n        进的良好生态。\n          综上，新职业的不断出现呼唤传统就业观念的升级，政府应加强舆论引导和政策支持，\n\n料       不断提高新职业的社会认可度。","figs":[],"state":"已标记","notes":[],"domains":["社会治理","公共管理"],"nature":"综合题","current":false,"links":[{"id":"k-782aeaaaaa443a6a","label":"新职业发展需要代际相互理解","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"两代人之间职业观存在冲突","why":"职业内涵拓展与老一辈对新职业认识不足之间的矛盾，解释了代际相互理解的必要性。","origin":"逐题标记"},{"id":"k-c40d603a5a00414f","label":"职业分类名录更新反映就业变化和政府服务调整","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M2","quote":"映着就业方向的重大变化，也体现着政府服务的与时俱进。","why":"将新职业和新工种纳入权威职业名录，是政府回应就业变化的具体例证。","origin":"逐题标记"},{"id":"k-088422e0d4693192","label":"探索在新兴职业领域增设职称系列","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M2","quote":"探索在新兴职业领域增设职称系列","why":"这项改革为原先缺少申报渠道的新兴职业从业者提供职称评价途径。","origin":"逐题标记"},{"id":"k-4fbb444d8345fc0c","label":"新兴专业职称实行分类评价并突出实绩","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M2","quote":"弱化学历、资历等要求，突出人才在专业领域取得的业绩、成果和行业认可度","why":"按从业群体设置评价标准，体现了政府对新兴领域人才的具体支持方式。","origin":"逐题标记"},{"id":"k-f9b2349587006493","label":"新兴职业职称改革促进人才集聚与产业发展","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"有利于吸引更多优秀人才，促进人才队伍建设","why":"人才吸引和队伍建设说明了政府改革如何推动人才发展与产业发展相互促进。","origin":"逐题标记"},{"id":"s-43e39afd29a17e74","label":"结合材料解释比喻并分析作用机制","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"社会成员间的互相理解与政府的适当引导往往是最好的调色剂。","why":"需把比喻还原为材料中的现实矛盾，再用个人案例和制度举措说明两种作用如何发挥。","origin":"逐题标记","originalId":"s-3956977e794d246a"}]},"江苏 2022 A类 申论#3":{"stem":"问题三\n\n                                              部\n           “给定资料 6”中的 W 市总工会在新业态群体中发展新会员的工作正在持续推进中，假\n\n\n\n                                               资\n        如你是该总工会一名工作人员，请你为招新工作拟定一份宣传单。（20 分）\n\n               料\n           要求：符合给定资料情境，有吸引力，操作性强，语言流畅，篇幅 350 字左右。","options":[],"answer":"","analysis":"问题三（20 分）      部\n                    内         w 市总工会招新\n          您想拥有一个完全属于你的组织吗？您想收获一份暖心的关爱吗？您想更好地融入城\n        市吗？别犹豫，加入 W 市总工会吧！\n                                                 料\n          在线申请入会，操作简单方便。您下载“暖心工惠 APP”，就可以在线申请入会，参加\n\n                                             资\n        定期组织的各项活动。截至目前，W 市总工会已针对网约车司机、外卖送餐员等群体成立工\n        会组织 35 家，吸纳工会会员 2563 人，线上线下两大类活动和二十个服务项目，等你来参与。\n\n\n        料                                部\n          困难有处说，问题有人解。总工会整合社区党群服务中心、网格服务站、物业用房，联\n        建共建快递小哥服务驿站 55 家，解决了快递末端用房紧张、快递员进小区难等问题。总工\n        会还常态化开展交通安全培训，提供线上线下 24 小时心理和法律咨询服务，构建了解忧帮\n\n    资   困关爱平台。\n                                         内\n          哪里有职工，哪里就有工会。总工会广泛开展政策咨询、技能培训、劳动权益维护等普\n\n\n    部   惠服务，打造出线上线下有机融合、协同互动的多元服务体系，有效提升了新业态职工的归\n        属感、幸福感。别再犹豫，现在就加入吧！","figs":[],"state":"已标记","notes":[],"domains":["社会治理"],"nature":"综合题","current":false,"links":[{"id":"k-a538f2c34315f1a4","label":"W 市新就业形态劳动者通过暖心工惠 APP 注册并在线申请入会","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M1","quote":"您下载并注册‘暖心工惠 APP’，就可以在线申请网上入会","why":"材料给出了招新宣传单需要说明的申请入口和步骤。","origin":"逐题标记"},{"id":"k-9200f68847653702","label":"工会整合社区服务场所共建快递小哥服务驿站","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"M1","quote":"联建共建快递小哥服务驿站 55 家","why":"驿站为快递员和配送员提供就近休息、饮水和充电的场所，是参考答案突出的入会宣传内容。","origin":"逐题标记"},{"id":"k-28ec2c5b68bf922b","label":"W 市工会为新业态职工提供政策咨询、技能培训和劳动权益维护","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"M1","quote":"政策咨询、技能培训、劳动权益维护等普惠服务","why":"这些普惠服务为宣传入会后的支持和权益保障提供了具体内容。","origin":"逐题标记"},{"id":"s-b92b682e65d12042","label":"面向招募对象提炼参与收益、办理步骤并发出行动号召","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"有吸引力，操作性强","why":"需从材料中筛选目标群体关心的服务，把申请流程写成可执行的步骤，并引导读者入会。","origin":"逐题标记","originalId":"s-7935322c5efbcf5a"}]},"江苏 2022 A类 申论#4":{"stem":"问题四\n\n\n        部                                   内\n           请结合你对“给定资料 7”中“如何更好地在变局中开新局，成为政府部门执政能力与\n        管理能力的试金石”这句话的理解，围绕“新时代潮涌新职业，新业态呼唤新作为”这一主\n\n\n         资\n        题，联系实际，写一篇对策性文章。（40 分）\n           要求：\n           （1）自选角度，自拟标题；\n\n    内      （2）参考给定资料，不拘泥于给定资料；\n           （3）观点明确，内容充实，结构完整，语言流畅；\n           （4）篇幅 1000 字左右。\n\n                           资\n                            料\n料                      部\n                   内\n                                               料\n                                            资\n        料                               部\n    资                                   内\n    部\n内\n                       料\n                   资      第 6 页 共 8 页","options":[],"answer":"","analysis":"内       问题四（40 分）\n                    完善政府服务与管理 推动新职业健康发展\n          穿梭于城市街头巷尾的“蓝骑士”，电脑屏幕前与陌生网友“侃大山”的管理师，陪伴\n\n                        料\n        在年迈老人身边的的助老员……当下，各类新兴职业层见叠出，可以说是中国新业态蓬勃发\n\n\n\n                    资      第 7 页 共 8 页\n\n                                      资\n                              部\n        展的真实写照。然而，它给社会发展带来新气象、新希望的同时，也给政府提出了新要求、\n        新挑战。因此，政府需要在变局中开新局，加强管理力度，拓宽服务宽度，主动作为，积极\n        创新，助推新职业健康发展。\n\n                         内\n          推动新职业健康发展，政府要与时俱进，依据热门行业，及时收录、公布新职业、新工\n        种，引导社会成员转变传统就业观念，提高新职业的社会认可度。新职业的快速兴起，让不\n        少思想保守的人一时无法接受，甚至对于部分新职业羞于启齿。正因如此，政府需要为新职\n        业、新工种“正名”，及时向社会公布权威职业名录，颁布职业分类大典，更新职业岗位信    料\n                                           部\n        息。除此之外，也要宣传普及新型职业的贡献率、社会价值以及未来的发展前景，提高公众\n        对其认知与了解。唯有如此，才能让更多人接纳新工种、新职业、新业态，让我们的就业市\n\n\n\n                                            资\n        场呈现百花齐放之姿。\n\n              料\n          推动新职业健康发展，政府要完善新兴职业人才评价标准，探索增设新职称，针对不同\n        群体量身定制评价标准，提高新职业人才职称评价的针对性、科学性和专业性。职称是评价\n\n\n        部                                 内\n        人才、推动产业发展的“指挥棒”。然而，新兴职业从业人员普遍面临职称申报无门的窘境。\n        对此，一方面，政府要尊重新职业特点，制定职称分类细则，让每一个新职业就业者有职称\n\n\n         资\n        可评，从而激发工作积极性、创造性。另一方面，也要完善评价内容，弱化学历、资历等要\n        求，突出人才在专业领域取得的业绩、成果和行业认可度，避免职称评价“一刀切”。\n          推动新职业健康发展，政府还要完善多渠道灵活就业的社会保障制度，给新业态职工提\n\n    内   供政策咨询、技能培训、劳动权益维护等普惠服务，提升其归属感、幸福感。当下，不少新\n        职业的就业形式打破了时间和空间的限制，原本的社会保障制度也需就此完善升级。例如，\n\n\n                         资\n        政府可以结合传统培训与数字培训方式，为希望从事新职业的劳动者提供精准培训，提高其\n        就业竞争力。此外，政府也需尽快出台新业态劳动用工管理政策，规范新职业的劳务报酬、\n\n\n                          料\n        社会保险、工时休假等，并通过加强行业监管，严惩侵犯新职业从业者权益的行为，从而保\n        障其合法权益。\n          新职业是中国产业升级的产物。作为人民的服务者，政府要持续作为，让新职业成为推\n\n料                    部\n        动发展、改善民生的新动能，让更多新职业从业者在各自的就业岗位上实现自我价值，大放\n        异彩啊！\n\n\n                  内\n                                           料\n                                          资\n        料                             部\n    资                                 内\n    部\n内\n                      料\n                  资     第 8 页 共 8 页","figs":[],"state":"已标记","notes":[],"domains":["公共管理","社会治理","经济"],"nature":"综合题","current":false,"links":[{"id":"k-4fe46080c7e55321","label":"新业态发展要求政府同步加强管理和拓宽服务","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"加强管理力度，拓宽服务宽度","why":"这一判断解释了新业态带来的治理挑战为何考验政府能力，也是全文组织对策的依据。","origin":"逐题标记"},{"id":"k-50995c87839c73f4","label":"更新权威职业名录并宣传职业价值有助于提高新职业社会认可度","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"引导社会成员转变传统就业观念，提高新职业的社会认可度。","why":"参考文章把公布新职业、新工种和宣传其社会贡献作为改善公众认知的具体措施。","origin":"逐题标记"},{"id":"k-ba003af392389fee","label":"新兴职业职称可探索增设系列并按职业特点突出业绩、成果和行业认可度","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M6","quote":"突出人才在专业领域取得的业绩、成果和行业认可度","why":"材料中的改革要求和分类评价实践支撑解决新兴职业申报无门、评价标准单一的对策。","origin":"逐题标记"},{"id":"k-69b8d0ced018c1c5","label":"灵活就业权益保障需要完善多渠道社会保障并规范新业态用工","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"完善多渠道灵活就业的社会保障制度","why":"材料提出灵活就业保障要求，参考文章据此提出规范劳务报酬、社会保险和工时休假等用工事项。","origin":"逐题标记"},{"id":"k-a36e11d3f49e4516","label":"工会可通过便捷入会和普惠服务覆盖新就业形态劳动者","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M7","quote":"广泛开展政策咨询、技能培训、劳动权益维护等普惠服务","why":"工会的线上入会和线下服务案例为扩大组织覆盖和服务可及性提供了做法。","origin":"逐题标记"},{"id":"s-ab43045e4cab9ffe","label":"结合材料解释引文所指现象及其对治理能力的要求","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请结合你对“给定资料 7”中","why":"题目要求从材料中的业态变化和服务需求出发，解释引文所说的能力考验。","origin":"逐题标记","originalId":"s-06c506c74276e984"},{"id":"s-b8139af04b609dce","label":"针对治理问题提出具体措施并论证措施的作用","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"联系实际，写一篇对策性文章。","why":"需要把材料中的问题转化为可实施的措施，并说明各项措施如何回应相应问题。","origin":"逐题标记","originalId":"s-e9b02ceaf5af4c4c"}]}},"mats":{"564c1ef6ae99242b":["材料1","材料一\n                                  部\n                     2022 年江苏公务员考试申论试题（A 卷）\n\n\n\n\n                            内\n            新时代带来新生活，新生活潮涌新职业。进入新时代以来，社会发展一日千里，基层\n        面貌日新月异，一些此前从未听说过的新职业、新人群在我们的生活中不断涌现，并渐成常\n        态。这些“后浪”新职业所引领的新业态既是社会发展的新气象、新希望，也对政府服务提\n        出了新要求、新挑战。                                          料\n                                                  部\n          一身“蓝骑士”套装，身披绶带，满面笑容，2021 年 4 月 27 日，来自 S 市的外卖骑手\n        小宋在人民大会堂郑重接下“全国五一劳动奖章”和证书，成为首位获此殊荣的快递人员。\n\n\n\n                                                   资\n        “兴奋、激动，为自己身为一名外卖骑手而自豪！”小宋的高兴藏也藏不住。\n\n                料\n          2014 年，为了与妻子团聚，小宋来到 S 市打拼。谈起最初选择快递工作的理由，小宋\n        说，“我要找一份收入稳定，能快速了解、融入这座国际化大城市的工作。”然而要熟悉这\n\n\n        部                                     内\n        座超大城市，并没有小宋想象中那么简单。不熟悉交通路线，总有送餐延误的时候，甚至免\n        不了被客户打个差评；遇到暴雨大风等极端天气，送餐途中必须格外小心。一次，他接了一\n\n\n         资\n        份披萨订单，由于商家没有给披萨密封，送达时已经凉透了。“客人不满意，我内心也很愧\n        疚。”思来想去，第二天小宋买了个毛绒玩具作为礼物向客人道歉，得到了对方的谅解。\n          抱着“既然做了就一定要做好”的决心，小宋克服了一个个困难。不熟悉交通路线，他\n\n    内   就利用休息时间反复研究区域道路；商务楼电梯等不及，他就靠爬楼梯节约时间；碰到客户\n        心情不好，他总能将心比心及时化解尴尬。凭着这股劲，仅用了 8 个月，小宋就从一名骑手\n\n\n                             资\n        被破格提升为凯旋路配送站的站长。站长的要求更高，既要懂配送，也要会规划，能够处理\n        好站点关于调度、客户纠纷、骑手意外事故等方面的问题。小宋曾在暴雨天给骑手送电瓶，\n\n\n                              料\n        曾在阴雨天和严寒时，熬上一锅红糖姜茶送到骑手休息的地铁站……如今，小宋又从站长晋\n        升为物流经理，主要从事骑手及站长的培训工作。截至目前，小宋已培训超过 400 名骑手，\n        每月还举办“站长班”，把站点管理经验传授给更多站长。\n\n料                       部\n          在小宋眼中，外卖骑手这个职业在社会中的作用越来越重要了，不仅是给客户送餐，还\n        能在基础物资保障、城市发展，甚至社会稳定方面发挥重要作用。在新冠肺炎疫情防控中，\n\n\n                    内\n        小宋和其他外卖骑手就发挥了独特作用。面对骤然增加的配送需求，当时已成为站点负责人\n        的他，重返一线骑手岗位，主动揽下医院、隔离点等高风险场所的送餐任务，还自掏腰包，\n        给站点的骑手们配备了 5000 只口罩。作为首位获得“全国五一劳动奖章”的外卖骑手，小\n        宋说：“这不仅是我个人的荣誉，更是属于数百万每日奔波在路上的外卖骑手群体的荣誉，\n        我要用更好的服务回馈社会，让这个行业得到更多的社会认可。”\n                                                  料",["a758d1c52c0259ca1b92.pdf",1]],"fc9f6d90816f244c":["材料2","材料二\n                                              资\n          00 后女生小叶今年刚从某科技学院毕业目前正准备考研，但“重度拖延症”和手机成\n\n\n        料\n        了她备考最大的“敌人”。两周前她收到了来自父母的“特殊礼物”——网络监督师在线服\n\n                                          部\n        务。每天都有一位学姐级别的网络监督师在“云端”监督她，“今天的学习任务完成了吗？”\n        小叶在学校附近独自租房，父母很不放心她的学习，偶然看到新闻报道里有“网络监督师”\n\n    资                                     内\n        服务，便下了单。尽管小叶对此哭笑不得，但体验了两周后，复习效率明显提高了。\n          走路、吃饭、乘车、购物……当代人不管在哪里、在做什么，似乎总是离不开智能手机。\n\n\n    部   “困在手机里太久了”，许多像小叶一样的年轻人，正在找回应当用在生活和学习上的时间。\n        有意思的是，年轻人找回时间的需要，还撑起了一个小众市场，网络监督师就是适配这个市\n        场的职业。网上专门提供学习监督服务的网店有很多，有些已经经营五六年了，根据需求可\n\n内       以选择标准监督和强力监督。一家网店客服说，他们会根据考试类别匹配相应的监督师，可\n        提供 500 元监督一个月、1200 元监督一个季度的服务。监督师会和客户一起制定计划，并\n\n                         料\n        给出备考建议，增加复习信心。此外，监督师服务内容还可私人订制，除了监督学习，还可\n\n\n\n                    资       第 1 页 共 8 页\n\n                                         资\n                                 部\n        以监督作息、减肥等。“偶尔也遇到半途而废的客户，但大多数人都能坚持下来，这类需要\n        还是蛮多的。”某监督网店的 95 后店主小马说。\n            2021 年“双十一”前夕，某大学研究生会公众号上一篇题为“不做吃土尾款人，当你\n\n                           内\n        看完这些书”的文章在朋友圈引起共鸣，“剁手党”们纷纷转发。文章推荐了《断舍离》《精\n        准购买》等书籍，希望大家“双十一”期间，购入真正适合自己的东西，理性购物。每年的\n        “双十一”，在成交额一再刷新的同时，也成为“非理性购物综合征”的集中爆发期。“乱\n        花渐欲迷人眼”，当自我约束与理性消费的呼声渐高，“网上导购师”这种时髦职业就诞生          料\n        了。\n\n                                                部\n            根据淘宝信息显示，最贵的网上导购师收费价格在 199 元一小时。导购师不仅可以帮助\n\n\n\n                                                 资\n        客户以最合理的价格达成交易，还会根据客户的需求提出合理购物建议，这种来自“网络达\n\n               料\n        人”的建议往往对客户帮助很大。有专家指出，“网上导购师”这种新职业是典型的“平台\n        +履约人”模式，相较于传统的“公司+雇员”关系，就业的稳定性固然差了些，但提供了最\n\n\n        部\n        大限度的平等和自由，因而越来越被年轻人所接受。\n                                             内\n            一个微信群有管理员不稀奇，但一个管理员“管”近 300 个群、数万网友，你听说过吗？\n\n\n         资\n        在 H 市中心的一所商务楼里，这样的社群管理师已经有近百人。他们每天活跃在电脑的一端，\n        与数以万计的网友“侃大山”，帮助企业维持群的活跃度、增强用户粘性。\n            “恭喜您抢到优惠券，记得截图去门店领取哦”“请不要在群里发小广告，违者要踢出\n\n    内   群哦”……安静的房间里，只听见电脑键盘啪嗒啪嗒的敲击声。一个年轻人端坐在桌子前，\n        一边点开微信群查看消息，一边选择合适的用语，及时回复群友。这就是社群管理师小徐每\n\n\n                            资\n        天的工作常态。小徐说：“一个社群管理师需要身兼气氛组、客服中心、接梗王等多重角色。\n        很多人平时看着闷声不响，线上却是气氛担当。通俗地说，闷骚的人比较适合这个职业。”\n\n\n                             料\n        当前线上社交已成为年轻人生活的重要一环，通过微信群来了解社会几乎是普适需求，而对\n        于一些偏内向的年轻人来说，当社群管理师则既提供了相对稳定的收入，又能扬个人所长。",["a758d1c52c0259ca1b92.pdf",1]],"7cd4dc31445f6096":["材料3","材料三\n\n料                      部\n            制冰师，听起来又冷又酷。随着北京冬奥会渐近的脚步，这个小众又新潮的职业走到了\n        聚光灯下。不久前，“相约北京”速度滑冰中国公开赛在国家速滑馆“冰丝带”精彩上演，\n\n\n                   内\n        高质量的冰面赢得国内外选手一致点赞。对于眼前的冰面，国家速滑馆运行团队武主任格外\n        自豪，“这是北京冬奥会使用的二氧化碳跨临界直冷制冰系统第三次正式制冰，中外制冰师\n        配合，仅用 10 天时间就完成了比赛场地制冰工作。”\n            为了打造“最快的冰”，加拿大的制冰师马克应邀来到了中国。年届花甲的他，拥有\n                                                 料\n        40 多年的制冰经验，参与过 5 届冬奥会速滑场馆的制冰工作。多名中国制冰师加入了制冰\n\n\n                                             资\n        团队，与马克的合作，让他们获益匪浅。制冰师小何还记得，在冰面上水时，马克要求必须\n        在 45 分钟内完成一圈，这样能够让冰面更平整。在此前，国内的制冰师很少有这样的严格\n\n\n        料\n        操作。“冰丝带”第二次制冰时，中方制冰师团队历时 7 天，独立完成了场馆训练道的制冰\n\n                                         部\n        工作。除了中方制冰师，还有一群年轻人在冰面上成长——国家速滑馆、国家游泳中心与某\n        高校共同开设的“双冰场馆制冰人才订单班”学员在这过程中也获益匪浅。通过近距离观察\n\n    资                                    内\n        制冰师工作，学员小吴感慨道：“相信在不远的将来，我也能成为独当一面的制冰师，做出\n        近乎完美的冰，我觉得这个职业很有前途。”小吴对未来的期许绝非盲目乐观，随着 2022\n\n\n    部   年北京冬奥会的临近，冰雪运动在我国呈现出“冷资源”释放“热效应”的好势头。京东平\n        台数据显示，今年“双十一”，滑雪品类自营订单量同比增长 23 倍，冰上装备成交额同比\n        提升 15 倍。申办冬奥成功以来，《冰雪运动发展规划（2016-2025 年）》《全国冰雪场地\n\n内       设施建设规划（2016-2022 年）》等文件陆续发布。群众参与冰雪运动的热情持续高涨，冰\n        雪场地设施的供给量也正在跟上。国家体育总局数据显示，截至 2021 年年初，全国已有 654\n\n                        料\n                    资      第 2 页 共 8 页\n\n                                           资\n                                   部\n        块标准滑雪场和 803 个室内外各类滑雪场，较 2015 年分别增长了 317%和 41%，本土制冰人\n        才将是北京冬奥会的重要遗产之一，“后冬奥”时代，制冰师大有可为。\n            助老员是做什么的，你知道吗？让我们来看看 M 市乌塔社区居家养老服务站助老员黄女\n\n                             内\n        士的工作内容。清晨，黄女士早早就来到社区，扫地擦桌，把卫生整理干净，为老人营造一\n        个舒适整洁的环境。接下来的工作就随着老人的兴趣和需求来安排，有时替老人铺纸研墨，\n        有时和老人打乒乓球，有时帮老人调整按摩椅……尽心尽责、亲力亲为，老人们提起黄女士，\n        总是赞不绝口。                                                料\n            柯奶奶是一位空巢老人，形单影只，黄女士时常会来陪她聊天，帮她整理房间。有一次，\n        柯奶奶不小心摔伤了腿，黄女士得知后，立刻和一位志愿者扶她去医院，帮她办住院手续，\n                                                     部\n                                                      资\n        出院后又登门看望她，帮她按摩双脚、整理房间等，老人说，黄女士对她就像对待亲生母亲\n        一样孝顺。\n                料\n            百善孝为先，随着老龄社会的到来，助老服务的社会需求越来越大，目前仅黄女士所在\n\n\n        部                                       内\n        的社区需要帮助的老人就有 300 多人。黄女士希望像她这样的助老员能够多一些，敬老、爱\n        老、助老，这是中国人的美德，也是中国梦重要的一部分。",["a758d1c52c0259ca1b92.pdf",2]],"be6086291d496eb8":["材料4","资  材料四\n            三百六十行，行行出状元。新职业的不断出现也在呼唤传统就业观念的升级。\n            11 月 7 日凌晨，在冰岛举行的 2021 英雄联盟全球总决赛中，代表中国 LPL 赛区出战的\n\n    内   EDG 战队夺冠，战报传来，全网沸腾。央视新闻在第一时间给予了祝贺。\n            以下是几个网友的发言。\n\n\n                              资\n            网友 A：央视新闻第一时间发文祝贺，太牛了！短短半小时，点赞数量就超过了 180 万，\n        不得不说，EDG 真的太有排面了！\n\n\n                               料\n            网友 B：我哭了，我哭的不是 EDG 夺冠，而是久久不被承认的自己。今天，激动也好、\n        流泪也好，全社会对待电子竞技应有一个理性的认知了。\n            网友 C：不得了，我们大学宿舍出现了“喊楼”的壮观场面。\n\n料                        部\n            J 省某职业学院电子竞技运动与管理专业 2019 级学生小胡是众多狂欢者中的一员。对\n        小胡来说。EDG 的这场胜利特别重要，从此他要大声地对家人说，他所学习和将要从事的，\n\n\n                    内\n        不是“难登大雅之堂”的游戏了，而是正经的职业了。\n            小胡高中时在一所重点中学就读，高二开始接触王者荣耀，巅峰时能打到全国前 100\n        名左右。那个时候的他特别自信，特别有执念，想走职业的路子，但是家里并不看好他，小\n        胡的父亲是一所中学的历史老师，一心希望儿子能考上一所 985 大学，他觉得以儿子的资质\n        将来在事业上一定能超过自己。\n                                                     料\n                           “打游戏不就是玩吗？这能有什么前途，我看就是不务正业！\n        说出去我都觉得丢人！”听了小胡的想法后，老胡火气很大。那段时间老胡整天虎着脸，小\n        胡也提不起学习的兴趣，最后，高考和电竞两头都落空了，高考分数只够得上现在的职业学资\n        料\n        院。职院就职院吧，在专业选择上父子俩又爆发了冲突，老胡希望儿子选财会专业或者经济\n\n                                            部\n        管理专业，小胡却只肯报电竞专业，谁说也不让步。这回老胡对儿子彻底失望了，甚至连开\n        学报到都拒绝送儿子去。\n\n    资                                      内\n            上了职业学院后，随着专业学习的不断深入，小胡对电竞有了更新的认识，“可能会让\n        大家有点意外，现在我打王者荣耀的时间其实少之又少，已经很少单纯为了玩而玩了，更多\n\n\n    部   时候是为校队比赛做一些集中训练，至于学校里电子竞技的实训课，也只是为了熟悉各款游\n        戏运营方面的课程上，比如营销、解说、直播、数据分析等等。”\n            今年暑假，小胡得到了一个去电竞俱乐部当夏令营助教的机会。夏令营里基本都是中学\n\n内       生，不少人也和曾经的小胡一样抱着打职业赛事的梦想。有一个学习成绩和电竞技术都挺不\n        错的孩子，在体验了 3 天的职业选手生活后，跟小胡说：      “可能这个行业并不是特别适合我。”\n\n                          料\n        这让小胡很触动，这孩子是一个天赋型的选手，但因为性格原因经常与教练和队友发生冲突，\n\n\n\n                     资       第 3 页 共 8 页\n\n                                           资\n                                   部\n        很难协作。“职业竞技跟打游戏完全是两回事，不仅需要天赋和苦练，还需要良好的心态和\n        沟通能力。”做助教的这段经历让小胡思考了很多，“今后我想做电竞教育，让喜欢电竞的\n        一些孩子在人生的关键阶段能够明确自己该怎么选择。不过今晚，我首先要跟我爸谈谈，我\n\n                             内\n        要告诉他，我所选择的，也是个有社会价值、有未来的职业。”\n            社会飞速发展，职业的内涵在不断延伸。当你问一个新职业人的父母，“您的孩子做什\n        么职业”时，他们常常语焉不详，甚至羞于启齿。对于职业发展，N 大学社会管理学院陈教\n        授说：“老一代有老一代的经验，新一代有新一代的兴趣，在鲜活的时代画板上，社会成员              料\n        间的互相理解与政府的适当引导往往是最好的调色剂。”不管老一辈理解不理解，电竞这个\n        行业是实实在在发展起来了。据《2021 年中国电竞行业研究报告》，电竞市场规模预计到\n                                                    部\n                                                     资\n        2022 年将增长至 1843.3 亿元。此次 EDG 夺冠引发的热潮将加速中国电竞产业的发展。近日，\n\n                料\n        2022 杭州亚运会组委会官宣，包括英雄联盟、王者荣耀（亚运版）等 8 个电竞小项加入亚\n        运会正式竞赛项目，这表明电子竞技进一步得到行业认可，小胡们的未来真不是梦。",["a758d1c52c0259ca1b92.pdf",3]],"85381e1195e82c29":["材料5","部   材料五\n                                               内\n           《中华人民共和国职业分类大典》是人力资源和社会保障部联合国家市场监督管理总局、\n\n\n         资\n        国家统计局，向社会公布的权威职业名录，自《中华人民共和国职业分类大典（2015 年版）》\n        颁布以来，已陆续发布了 4 批新职业，每次颁布都有一批出人意料的职业上榜，让人大跌眼\n        镜。比如 2019 年公布的新职业中，电子竞技员、电子竞技运营师就赫然在列。2020 年的更\n\n    内   新中加入了“互联网营销师”等 9 个新职业，以及“直播销售员”等 5 个新工种。2021 年 3\n        月 18 日公布了第 4 批新职业，集成电路技术人员、企业合规师、汽车救援员、酒体设计师\n\n\n                              资\n        等 18 个新职业闪亮登场。这些新收录的职业和工种，基本上对应着时下热门的行业，既反\n        映着就业方向的重大变化，也体现着政府服务的与时俱进。\n\n\n                               料\n            “搞科普也能评职称了！我要申报！”第一次在朋友圈看到这个消息，果壳网首席执行\n        官嵇先生眼前一亮，马上打电话让公司的 HR 去打听具体情况。嵇先生是位科普“网红”，\n        以笔名“姬十三”火出圈的他，从读博开始就与科普结下不解之缘，深耕其中十几年，先后\n\n料                        部\n        创办了科学松鼠会、果壳网等一批科普品牌，让原本“高冷”的科普知识妙趣横生，受到广\n        大年轻人热捧。2020 年底，B 市在全国率先推出科学传播专业职称，嵇先生评上了正高级职\n\n\n                    内\n        称，和图书资料领域其他专家学者一样，成了一名“研究馆员”。\n            新兴专业职称怎么评？为了避免“一把尺子量到底”，各地各部门针对不同群体量身定\n        制评价标准，弱化学历、资历等要求，突出人才在专业领域取得的业绩、成果和行业认可度，\n        实行“干什么，评什么”。L 省绿蔬种植专业合作社带头人沈先生今年评上了“高级农艺师”，\n        这是 L 省新型职业农民职称中的副高级。评审组专家来到合作社，进大棚、参观养殖场，对\n                                                    料\n        沈先生的业绩现场“验收”，这样的评审方式让他惊喜不已。\n                                                资\n            职称是评价人才、推动产业发展的“指挥棒”。随着我国产业结构升级换代，新技术、\n\n\n        料\n        新产业层出不穷。为改变新兴职业从业人员普遍面临职称申报无门的窘境，人社部《关于深\n\n                                           部\n        化职称制度改革的意见》明确提出，“探索在新兴职业领域增设职称系列”，这给广大新兴\n        领域人才打开了职称的大门。“对于企业和行业来说，这有利于吸引更多优秀人才，带动行\n\n    资                                      内\n        业的人才队伍建设，形成人才促进产业发展，产业发展又促进人才发展的良好生态。”G 省\n        人社厅相关负责同志说。",["a758d1c52c0259ca1b92.pdf",4]],"b8a34a54612ba9e0":["材料6","部       材料六\n            “瞧，这是工会给我们免费提供的围脖和手套，赶上这大冷天真是太实用了！”这几天，\n        W 市高新区快递小哥小田逢人就念叨加入工会的好处，小田是 11 月初加入到工会组织中。\n\n内       今年以来，W 市总工会针对新业态职工增长快、权益维护难等情况，力推新就业形态建会入\n        会工作，在网约车司机、快递员、网约送餐员等群体成立工会组织 35 家，吸纳工会会员 2563\n        人。\n                         料\n                     资       第 4 页 共 8 页\n\n                                         资\n                                 部\n            “您下载并注册‘暖心工惠 APP’，就可以在线申请网上入会，成为工会会员后就能参\n        加我们定期组织的各项活动。”11 月 27 日上午，在 W 市人才交流中心广场，市总工会工作\n\n                           内\n        人员正在进行“招新”宣传。这里是 W 市“工会进万家·新就业形态劳动者温暖行动”服务\n        月工作推进会现场，会上发布总工会面向新业态从业人员开展的一系列服务活动，包含为新\n        业态从业人员送出 8000 个体检名额、合计 200 万元的体检服务在内的线上线下两大活动和\n        六大类二十个服务项目，重点聚焦快递员、外卖配送员、网约车司机等新就业群体开展服务         料\n                                               部\n        活动。活动现场，参加义诊的市人民医院医务人员正在为顺丰快递员小张测量血压，小张表\n        示：“快递员工作经常早出晚归，吃饭没个准点，这次活动给我们普及健康知识，给身体提\n\n\n\n                                                资\n        个醒，真是太重要了。”\n\n               料\n            “现在天越来越冷，不忙的时候我们都会到就近的驿站喝喝水，歇歇脚，充充电，感觉\n        很暖心。”最近寒潮来袭，位于 W 市中心的几家工会服务驿站比往常热闹了许多，送餐间隙，\n\n\n        部                                    内\n        这里成为了网约送餐员和快递小哥们的“避风港”。近年来，W 市总工会整合社区党群服务\n        中心、网格服务站、物业用房，联建共建快递小哥服务驿站 55 家，解决了快递末端用房紧\n\n\n         资\n        张、快递员进小区难等问题。针对新业态工作特点，市总工会常态化开展交通安全培训，开\n        通线上线下 24 小时心理和法律咨询服务，为新就业形态群体构建了“困难有处说，问题有\n        人解”的关爱平台。\n\n    内       “哪里有职工，哪里就有工会组织。”W 市总工会严主席说，“新职业群体以灵活就业\n        为主，数量庞大，目前仅 W 市就有 100 多万人，其中许多人对工会的职能、意义缺乏了解，\n\n\n                            资\n        这给我们发展新会员带来挑战。”为最大限度地将灵活就业人员组织到工会中来，W 市总工\n        会在新业态职工中广泛开展政策咨询、技能培训、劳动权益维护等普惠服务，打造出线上线\n\n\n                             料\n        下有机融合、协同互动的多元服务体系，有效提升了新业态职工的归属感、幸福感。",["a758d1c52c0259ca1b92.pdf",4]],"78ad2e491363eaee":["材料7","材料七\n            过去的两年，疫情与社会发展和百姓生活相伴相随，但危机往往育新机，变局中常可开\n\n料                      部\n        新局。正是在疫情防控期间，一些新职业得以大显身手，新业态得到了蓬勃发展。“云办公”\n        赋能企业复工复产，在线办公成复工主流。\n\n\n                   内\n            在线政务加快发展，各地数字政府建设经受住了疫情考验。宅生活催生各类“云消费”，\n        “云购物”“云娱乐”“云旅游”等各类“云经济”逆势崛起……红红火火的新业态、新模\n        式，不仅拓宽了消费市场的新空间，也创造了经济发展的新机遇。\n\n                                                料\n            随着新业态、新模式的持续加快发展，我国灵活就业规模达到 2 亿人，这些灵活就业人\n        群以新职业为主体，其中网约车司机、互联网营销师、骑手、快递员等群体较大，还有设计\n\n\n                                             资\n        师、主持人、摄影师等自由职业者。展望未来，高端岗位的灵活就业人群会进一步扩大。今\n        年 4 月，习近平总书记在广西考察时指出，要完善多渠道灵活就业的社会保障制度，维护好\n\n\n        料\n        快递小哥、外卖配送员等的合法权益。不久前，全国首个灵活就业人员合法权益保障中心在\n\n                                         部\n        广西南宁正式揭牌，集中解决灵活就业人员劳务报酬纠纷中“难办、难认、难等”等维权难\n        问题。在新业态的发展壮大过程中，政府服务从未缺席。\n\n    资                                    内\n            新技术层出不穷，新业态风起云涌，新模式激荡澎湃，这是中国经济强势回暖的写照。\n        如何更好地在变局中开新局，成为政府部门执政能力与管理能力的试金石。只有不断加强政\n\n\n    部   府管理的力度，不断拓宽政府服务的宽度，才能汇聚起强大动力，推动中国经济实现高质量\n        发展，向第二个百年的奋斗目标努力迈进。",["a758d1c52c0259ca1b92.pdf",5]]}};
